-- MAGIC %md
-- MAGIC
-- MAGIC ## Tests for `user_agent.sql`
-- MAGIC
-- MAGIC Each cell fails with `raise_error` and lists the failed cases. Create the functions from `../user_agent.sql` in the same schema first.
-- MAGIC
-- MAGIC The expected values are the results of ua-parser 1.0 (uap-core 202610), except the cases marked `differs from ua-parser`:
-- MAGIC the security scanners, and the Samsung, webview and Nexus devices that ua-parser maps differently.
-- MAGIC The cases after the Nikto case are from real HTTP logs.

-- COMMAND ----------

SELECT if(count(*) = 0, 'ok: user_agent_parse',
          raise_error(concat('user_agent_parse: ', string(count(*)), ' failed: ', array_join(collect_list(failure), ' | '))))
FROM (
  SELECT concat(coalesce(input, 'NULL'), ' => ', coalesce(actual, 'NULL'), ', expected ', coalesce(expected, 'NULL')) AS failure
  FROM (
    SELECT input, expected, to_json(user_agent_parse(input)) AS actual
    FROM VALUES
